mapper.select:
SELECT v.id, v.plate_number as plateNumber, v.brand, v.seats, v.status, v.fuel_consumption as fuelConsumption, v.route_id as routeId, r.name as routeName, v.driver_name as driverName, v.driver_phone as driverPhone, v.purchase_date as purchaseDate, v.last_maintenance as lastMaintenance, v.next_maintenance as nextMaintenance, v.mileage, v.remark, v.create_time as createTime FROM biz_vehicle v LEFT JOIN biz_route r ON v.route_id = r.id WHERE v.deleted = 0
AND v.plate_number LIKE CONCAT('%', #{query.plateNumber}, '%')
AND v.status = #{query.status}
AND v.route_id = #{query.routeId}
AND v.brand LIKE CONCAT('%', #{query.brand}, '%')
ORDER BY v.create_time DESC
